//! Lossless Rowan execution for parser tables generated by `gerbil-parser`.
//!
//! Grammar declarations and LR conflict resolution remain owned by Scheme at
//! AOT time. This crate executes only the resulting immutable tables.

use std::collections::HashMap;
use std::fmt::Write as _;
use std::sync::Arc;

use rowan::{GreenNode, GreenNodeBuilder};
use sha2::{Digest, Sha256};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum KindCategory {
    Node,
    Token,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct KindSpec {
    pub name: &'static str,
    pub category: KindCategory,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct TerminalSpec {
    pub name: &'static str,
    pub syntax_kind: u16,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LexicalExpr {
    Whitespace,
    HorizontalWhitespace,
    Newline,
    DecimalDigits,
    Number,
    NumberLiteral {
        prefixes: &'static [&'static str],
        separator: &'static str,
        suffixes: &'static [&'static str],
        leading_period: bool,
        trailing_period: bool,
    },
    Identifier,
    QuotedString(&'static [&'static str]),
    Heredoc,
    LineComment(&'static [&'static str]),
    BlockComment {
        opening: &'static str,
        closing: &'static str,
    },
    NestedBlockComment {
        opening: &'static str,
        closing: &'static str,
    },
    Choice(&'static [LexicalExpr]),
    Literals(&'static [&'static str]),
    Fallback,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct LexicalRule {
    pub terminal: &'static str,
    pub expression: LexicalExpr,
    pub precedence: i32,
    pub extra: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Terminal {
    Eof,
    Literal(&'static str),
    Token(&'static str),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ParserAction {
    Shift(u32),
    Reduce(u32),
    Accept,
    RejectNonAssoc,
    Fork(&'static [ParserAction]),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ActionEntry {
    pub terminal: Terminal,
    pub action: ParserAction,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct GotoEntry {
    pub nonterminal: &'static str,
    pub state: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Symbol {
    Terminal(Terminal),
    Nonterminal(&'static str),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum OperandAction {
    Field(&'static str),
    Alias(u16),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Operand {
    pub symbol: Symbol,
    pub actions: &'static [OperandAction],
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Reduction {
    Pass,
    Concat,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Production {
    pub lhs: &'static str,
    pub rhs: &'static [Operand],
    pub reduction: Reduction,
    pub dynamic_precedence: i32,
}

#[derive(Clone, Copy, Debug)]
pub struct LanguageSpec {
    pub language: &'static str,
    pub version: &'static str,
    pub contract: &'static str,
    pub grammar_digest: &'static str,
    pub case_insensitive: bool,
    pub root_kind: u16,
    pub kinds: &'static [KindSpec],
    pub terminals: &'static [TerminalSpec],
    pub lexical_rules: &'static [LexicalRule],
    pub actions: &'static [&'static [ActionEntry]],
    pub gotos: &'static [&'static [GotoEntry]],
    pub productions: &'static [Production],
}

#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct SyntaxKind(pub u16);

#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum GerbilLanguage {}

impl rowan::Language for GerbilLanguage {
    type Kind = SyntaxKind;

    fn kind_from_raw(raw: rowan::SyntaxKind) -> Self::Kind {
        SyntaxKind(raw.0)
    }

    fn kind_to_raw(kind: Self::Kind) -> rowan::SyntaxKind {
        rowan::SyntaxKind(kind.0)
    }
}

pub type SyntaxNode = rowan::SyntaxNode<GerbilLanguage>;
pub type SyntaxToken = rowan::SyntaxToken<GerbilLanguage>;

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ParseReceipt {
    pub language: &'static str,
    pub version: &'static str,
    pub contract: &'static str,
    pub grammar_digest: &'static str,
    pub source_digest: String,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SelectiveGlrReceipt {
    pub branch_budget: usize,
    pub branches_explored: usize,
    pub speculative_branches_explored: usize,
    pub max_speculative_depth: usize,
    pub merged_branches: usize,
    pub successful_completions: usize,
    pub distinct_completions: usize,
    pub winner_reason: &'static str,
    pub dynamic_score: i32,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Diagnostic {
    pub reason_kind: &'static str,
    pub byte_offset: usize,
    pub message: String,
}

#[derive(Clone, Debug)]
pub struct Parse {
    green: GreenNode,
    kinds: Arc<[KindSpec]>,
    receipt: ParseReceipt,
    selective_glr: SelectiveGlrReceipt,
}

impl Parse {
    #[must_use]
    pub fn syntax(&self) -> SyntaxNode {
        SyntaxNode::new_root(self.green.clone())
    }

    #[must_use]
    pub fn receipt(&self) -> &ParseReceipt {
        &self.receipt
    }

    #[must_use]
    pub fn selective_glr_receipt(&self) -> &SelectiveGlrReceipt {
        &self.selective_glr
    }

    #[must_use]
    pub fn kind_name(&self, kind: SyntaxKind) -> Option<&str> {
        self.kinds.get(usize::from(kind.0)).map(|kind| kind.name)
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ParseError {
    pub receipt: ParseReceipt,
    pub diagnostic: Box<Diagnostic>,
    pub selective_glr: Option<Box<SelectiveGlrReceipt>>,
}

#[derive(Clone, Debug)]
struct ParserFailure {
    diagnostic: Diagnostic,
    selective_glr: Option<Box<SelectiveGlrReceipt>>,
}

#[derive(Clone, Debug)]
struct Token<'source> {
    terminal: &'static str,
    syntax_kind: u16,
    text: &'source str,
    start: usize,
    end: usize,
    extra: bool,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct Child {
    field: Option<&'static str>,
    value: Value,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum Value {
    Token(usize),
    Node {
        kind: u16,
        start: usize,
        end: usize,
        children: Vec<Child>,
    },
    Fragment(Vec<Child>),
}

impl Value {
    fn start(&self, tokens: &[Token<'_>], fallback: usize) -> usize {
        match self {
            Self::Token(index) => tokens[*index].start,
            Self::Node { start, .. } => *start,
            Self::Fragment(children) => children
                .first()
                .map_or(fallback, |child| child.value.start(tokens, fallback)),
        }
    }

    fn end(&self, tokens: &[Token<'_>], fallback: usize) -> usize {
        match self {
            Self::Token(index) => tokens[*index].end,
            Self::Node { end, .. } => *end,
            Self::Fragment(children) => children
                .last()
                .map_or(fallback, |child| child.value.end(tokens, fallback)),
        }
    }

    fn into_children(self) -> Vec<Child> {
        match self {
            Self::Fragment(children) => children,
            value => vec![Child { field: None, value }],
        }
    }
}

pub fn parse(spec: &'static LanguageSpec, source: &str) -> Result<Parse, ParseError> {
    let receipt = receipt(spec, source);
    validate_spec(spec).map_err(|message| ParseError {
        receipt: receipt.clone(),
        diagnostic: Box::new(Diagnostic {
            reason_kind: "invalid-aot-artifact",
            byte_offset: 0,
            message,
        }),
        selective_glr: None,
    })?;
    let tokens = lex(spec, source).map_err(|diagnostic| ParseError {
        receipt: receipt.clone(),
        diagnostic: Box::new(diagnostic),
        selective_glr: None,
    })?;
    let (root, selective_glr) = parse_tokens(spec, &tokens).map_err(|failure| ParseError {
        receipt: receipt.clone(),
        diagnostic: Box::new(failure.diagnostic),
        selective_glr: failure.selective_glr,
    })?;
    let green = build_green(spec, source, &tokens, &root).map_err(|message| ParseError {
        receipt: receipt.clone(),
        diagnostic: Box::new(Diagnostic {
            reason_kind: "invalid-cst",
            byte_offset: 0,
            message,
        }),
        selective_glr: None,
    })?;
    Ok(Parse {
        green,
        kinds: Arc::from(spec.kinds),
        receipt,
        selective_glr,
    })
}

fn receipt(spec: &LanguageSpec, source: &str) -> ParseReceipt {
    let digest = Sha256::digest(source.as_bytes());
    let mut encoded = String::with_capacity(71);
    encoded.push_str("sha256:");
    for byte in digest {
        let _ = write!(encoded, "{byte:02x}");
    }
    ParseReceipt {
        language: spec.language,
        version: spec.version,
        contract: spec.contract,
        grammar_digest: spec.grammar_digest,
        source_digest: encoded,
    }
}

fn validate_spec(spec: &LanguageSpec) -> Result<(), String> {
    if spec.grammar_digest.len() != 71 || !spec.grammar_digest.starts_with("sha256:") {
        return Err("grammar digest is not a canonical SHA-256 identity".into());
    }
    if spec.kinds.len() > usize::from(u16::MAX) + 1 {
        return Err("syntax-kind catalog exceeds Rowan u16 identity space".into());
    }
    if usize::from(spec.root_kind) >= spec.kinds.len()
        || spec.kinds[usize::from(spec.root_kind)].category != KindCategory::Node
    {
        return Err("root kind is not a declared node".into());
    }
    if spec.actions.len() != spec.gotos.len() {
        return Err("LR action and goto state counts differ".into());
    }
    for terminal in spec.terminals {
        let Some(kind) = spec.kinds.get(usize::from(terminal.syntax_kind)) else {
            return Err(format!(
                "terminal {} has an unknown syntax kind",
                terminal.name
            ));
        };
        if kind.category != KindCategory::Token {
            return Err(format!(
                "terminal {} does not resolve to a token kind",
                terminal.name
            ));
        }
    }
    for rule in spec.lexical_rules {
        if !spec
            .terminals
            .iter()
            .any(|terminal| terminal.name == rule.terminal)
        {
            return Err(format!(
                "lexical rule references unknown terminal {}",
                rule.terminal
            ));
        }
        validate_lexical_expression(&rule.expression)?;
    }
    let state_count = spec.actions.len();
    for row in spec.actions {
        for entry in *row {
            validate_parser_action(&entry.action, state_count, spec.productions.len())?;
        }
    }
    for row in spec.gotos {
        for entry in *row {
            if entry.state as usize >= state_count {
                return Err(format!("goto targets unknown state {}", entry.state));
            }
        }
    }
    for production in spec.productions {
        for operand in production.rhs {
            for action in operand.actions {
                if let OperandAction::Alias(kind) = action {
                    let Some(specification) = spec.kinds.get(usize::from(*kind)) else {
                        return Err(format!("alias references unknown syntax kind {kind}"));
                    };
                    if specification.category != KindCategory::Node {
                        return Err(format!("alias references non-node syntax kind {kind}"));
                    }
                }
            }
        }
    }
    Ok(())
}

fn validate_parser_action(
    action: &ParserAction,
    state_count: usize,
    production_count: usize,
) -> Result<(), String> {
    match action {
        ParserAction::Shift(state) if *state as usize >= state_count => {
            Err(format!("shift targets unknown state {state}"))
        }
        ParserAction::Reduce(production) if *production as usize >= production_count => {
            Err(format!("reduce references unknown production {production}"))
        }
        ParserAction::Fork([]) => Err("selective-GLR fork has no branches".into()),
        ParserAction::Fork(branches) => {
            for branch in *branches {
                validate_parser_action(branch, state_count, production_count)?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

fn validate_lexical_expression(expression: &LexicalExpr) -> Result<(), String> {
    fn nonempty(values: &[&str]) -> bool {
        values.iter().all(|value| !value.is_empty())
    }

    match expression {
        LexicalExpr::NumberLiteral {
            prefixes,
            separator,
            suffixes,
            ..
        } if separator.chars().count() != 1 || !nonempty(prefixes) || !nonempty(suffixes) => {
            Err("profiled number contains an invalid separator, prefix, or suffix".into())
        }
        LexicalExpr::QuotedString(delimiters) if delimiters.is_empty() || !nonempty(delimiters) => {
            Err("quoted string requires non-empty delimiters".into())
        }
        LexicalExpr::LineComment(prefixes) if prefixes.is_empty() || !nonempty(prefixes) => {
            Err("line comment requires non-empty prefixes".into())
        }
        LexicalExpr::BlockComment { opening, closing }
        | LexicalExpr::NestedBlockComment { opening, closing }
            if opening.is_empty() || closing.is_empty() =>
        {
            Err("block comment requires non-empty delimiters".into())
        }
        LexicalExpr::Choice([]) => Err("lexical choice requires at least one alternative".into()),
        LexicalExpr::Choice(expressions) => {
            for alternative in *expressions {
                validate_lexical_expression(alternative)?;
            }
            Ok(())
        }
        LexicalExpr::Literals(values) if values.is_empty() || !nonempty(values) => {
            Err("literal expression requires non-empty spellings".into())
        }
        _ => Ok(()),
    }
}

fn lex<'source>(
    spec: &LanguageSpec,
    source: &'source str,
) -> Result<Vec<Token<'source>>, Diagnostic> {
    let terminal_kinds = spec
        .terminals
        .iter()
        .map(|terminal| (terminal.name, terminal.syntax_kind))
        .collect::<HashMap<_, _>>();
    let mut offset = 0;
    let mut tokens = Vec::new();
    while offset < source.len() {
        if !source.is_char_boundary(offset) {
            return Err(Diagnostic {
                reason_kind: "lexer-offset",
                byte_offset: offset,
                message: "lexer offset is not a UTF-8 boundary".into(),
            });
        }
        let mut selected: Option<(&LexicalRule, usize, usize)> = None;
        for (order, rule) in spec.lexical_rules.iter().enumerate() {
            let Some(end) = lexical_end(&rule.expression, source, offset) else {
                continue;
            };
            if end <= offset {
                continue;
            }
            let replace = selected.is_none_or(|(current, current_end, current_order)| {
                end > current_end
                    || (end == current_end && rule.precedence > current.precedence)
                    || (end == current_end
                        && rule.precedence == current.precedence
                        && order < current_order)
            });
            if replace {
                selected = Some((rule, end, order));
            }
        }
        let Some((rule, end, _)) = selected else {
            return Err(Diagnostic {
                reason_kind: "lexical-rejected",
                byte_offset: offset,
                message: "no generated lexical rule consumed the source".into(),
            });
        };
        let Some(&syntax_kind) = terminal_kinds.get(rule.terminal) else {
            return Err(Diagnostic {
                reason_kind: "invalid-aot-artifact",
                byte_offset: offset,
                message: format!("unknown generated terminal {}", rule.terminal),
            });
        };
        tokens.push(Token {
            terminal: rule.terminal,
            syntax_kind,
            text: &source[offset..end],
            start: offset,
            end,
            extra: rule.extra,
        });
        offset = end;
    }
    Ok(tokens)
}

fn lexical_end(expression: &LexicalExpr, source: &str, offset: usize) -> Option<usize> {
    let suffix = &source[offset..];
    match expression {
        LexicalExpr::Whitespace => consume_while(source, offset, char::is_whitespace),
        LexicalExpr::HorizontalWhitespace => {
            consume_while(source, offset, |character| matches!(character, ' ' | '\t'))
        }
        LexicalExpr::Newline => {
            consume_while(source, offset, |character| matches!(character, '\r' | '\n'))
        }
        LexicalExpr::DecimalDigits => {
            consume_while(source, offset, |character| character.is_numeric())
        }
        LexicalExpr::Number => number_end(source, offset),
        LexicalExpr::NumberLiteral {
            prefixes,
            separator,
            suffixes,
            leading_period,
            trailing_period,
        } => number_literal_end(
            source,
            offset,
            prefixes,
            separator,
            suffixes,
            *leading_period,
            *trailing_period,
        ),
        LexicalExpr::Identifier => identifier_end(source, offset),
        LexicalExpr::QuotedString(delimiters) => delimiters
            .iter()
            .find_map(|delimiter| quoted_string_end(source, offset, delimiter)),
        LexicalExpr::Heredoc => heredoc_end(source, offset),
        LexicalExpr::LineComment(prefixes) => line_comment_end(source, offset, prefixes),
        LexicalExpr::BlockComment { opening, closing } => {
            block_comment_end(source, offset, opening, closing, false)
        }
        LexicalExpr::NestedBlockComment { opening, closing } => {
            block_comment_end(source, offset, opening, closing, true)
        }
        LexicalExpr::Choice(expressions) => expressions
            .iter()
            .filter_map(|expression| lexical_end(expression, source, offset))
            .max(),
        LexicalExpr::Literals(values) => values
            .iter()
            .filter(|value| suffix.starts_with(**value))
            .max_by_key(|value| value.len())
            .map(|value| offset + value.len()),
        LexicalExpr::Fallback => suffix
            .chars()
            .next()
            .map(|character| offset + character.len_utf8()),
    }
}

fn longest_literal<'a>(source: &str, offset: usize, values: &'a [&str]) -> Option<&'a str> {
    values
        .iter()
        .copied()
        .filter(|value| source[offset..].starts_with(value))
        .max_by_key(|value| value.len())
}

fn quoted_string_end(source: &str, offset: usize, delimiter: &str) -> Option<usize> {
    if delimiter.is_empty() || !source[offset..].starts_with(delimiter) {
        return None;
    }
    let mut cursor = offset + delimiter.len();
    while cursor < source.len() {
        if source[cursor..].starts_with('\\') {
            cursor += '\\'.len_utf8();
            let escaped = source[cursor..].chars().next()?;
            cursor += escaped.len_utf8();
        } else if source[cursor..].starts_with(delimiter) {
            let next = cursor + delimiter.len();
            if source[next..].starts_with(delimiter) {
                cursor = next + delimiter.len();
            } else {
                return Some(next);
            }
        } else {
            cursor += source[cursor..].chars().next()?.len_utf8();
        }
    }
    None
}

fn line_comment_end(source: &str, offset: usize, prefixes: &[&str]) -> Option<usize> {
    let prefix = longest_literal(source, offset, prefixes)?;
    let body = offset + prefix.len();
    Some(
        source[body..]
            .char_indices()
            .find_map(|(relative, character)| {
                matches!(character, '\n' | '\r').then_some(body + relative)
            })
            .unwrap_or(source.len()),
    )
}

fn block_comment_end(
    source: &str,
    offset: usize,
    opening: &str,
    closing: &str,
    nested: bool,
) -> Option<usize> {
    if opening.is_empty() || closing.is_empty() || !source[offset..].starts_with(opening) {
        return None;
    }
    let mut cursor = offset + opening.len();
    let mut depth = 1_usize;
    while cursor < source.len() {
        if nested && source[cursor..].starts_with(opening) {
            depth += 1;
            cursor += opening.len();
        } else if source[cursor..].starts_with(closing) {
            depth -= 1;
            cursor += closing.len();
            if depth == 0 {
                return Some(cursor);
            }
        } else {
            cursor += source[cursor..].chars().next()?.len_utf8();
        }
    }
    None
}

fn identifier_end(source: &str, offset: usize) -> Option<usize> {
    let mut characters = source[offset..].char_indices();
    let (_, first) = characters.next()?;
    if first != '_' && !first.is_alphabetic() {
        return None;
    }
    let mut end = offset + first.len_utf8();
    for (_, character) in characters {
        if character != '_'
            && character != '-'
            && !character.is_alphabetic()
            && !character.is_numeric()
        {
            break;
        }
        end += character.len_utf8();
    }
    Some(end)
}

fn number_end(source: &str, offset: usize) -> Option<usize> {
    let whole_end = consume_while(source, offset, |character| character.is_numeric())?;
    let fraction_end = if source[whole_end..].starts_with('.') {
        let digits_start = whole_end + 1;
        consume_while(source, digits_start, |character| character.is_numeric()).unwrap_or(whole_end)
    } else {
        whole_end
    };
    let Some(exponent) = source[fraction_end..].chars().next() else {
        return Some(fraction_end);
    };
    if !matches!(exponent, 'e' | 'E') {
        return Some(fraction_end);
    }
    let mut digits_start = fraction_end + exponent.len_utf8();
    if let Some(sign) = source[digits_start..].chars().next()
        && matches!(sign, '+' | '-')
    {
        digits_start += sign.len_utf8();
    }
    consume_while(source, digits_start, |character| character.is_numeric()).or(Some(fraction_end))
}

fn number_literal_end(
    source: &str,
    offset: usize,
    prefixes: &[&str],
    separator: &str,
    suffixes: &[&str],
    leading_period: bool,
    trailing_period: bool,
) -> Option<usize> {
    let separator = separator.chars().next()?;
    let radix_end = longest_literal(source, offset, prefixes).and_then(|prefix| {
        let base = match prefix.chars().last()?.to_ascii_lowercase() {
            'b' => 2,
            'o' => 8,
            'x' => 16,
            _ => return None,
        };
        separated_digits_end(source, offset + prefix.len(), base, separator)
    });
    let number_end = radix_end.or_else(|| {
        decimal_mantissa_end(source, offset, separator, leading_period, trailing_period)
            .map(|mantissa| exponent_end(source, mantissa, separator))
    })?;
    Some(
        longest_literal(source, number_end, suffixes)
            .map_or(number_end, |suffix| number_end + suffix.len()),
    )
}

fn separated_digits_end(source: &str, offset: usize, base: u32, separator: char) -> Option<usize> {
    let mut characters = source[offset..].char_indices().peekable();
    let (_, first) = characters.next()?;
    first.to_digit(base)?;
    let mut end = offset + first.len_utf8();
    while let Some((relative, character)) = characters.next() {
        if character.is_digit(base) {
            end = offset + relative + character.len_utf8();
        } else if character == separator
            && characters
                .peek()
                .is_some_and(|(_, next)| next.is_digit(base))
        {
            let (digit_relative, digit) = characters.next().expect("peeked digit exists");
            end = offset + digit_relative + digit.len_utf8();
        } else {
            break;
        }
    }
    Some(end)
}

fn decimal_mantissa_end(
    source: &str,
    offset: usize,
    separator: char,
    leading_period: bool,
    trailing_period: bool,
) -> Option<usize> {
    if leading_period && source[offset..].starts_with('.') {
        return separated_digits_end(source, offset + 1, 10, separator);
    }
    let whole_end = separated_digits_end(source, offset, 10, separator)?;
    if !source[whole_end..].starts_with('.') {
        return Some(whole_end);
    }
    separated_digits_end(source, whole_end + 1, 10, separator)
        .or_else(|| trailing_period.then_some(whole_end + 1))
        .or(Some(whole_end))
}

fn exponent_end(source: &str, mantissa_end: usize, separator: char) -> usize {
    let Some(indicator) = source[mantissa_end..].chars().next() else {
        return mantissa_end;
    };
    if !matches!(indicator, 'e' | 'E') {
        return mantissa_end;
    }
    let mut digits_start = mantissa_end + indicator.len_utf8();
    if let Some(sign) = source[digits_start..].chars().next()
        && matches!(sign, '+' | '-')
    {
        digits_start += sign.len_utf8();
    }
    separated_digits_end(source, digits_start, 10, separator).unwrap_or(mantissa_end)
}

fn heredoc_end(source: &str, offset: usize) -> Option<usize> {
    if !source[offset..].starts_with("<<") {
        return None;
    }
    let mut marker_start = offset + 2;
    if source[marker_start..].starts_with('-') {
        marker_start += 1;
    }
    let marker_end = identifier_end(source, marker_start)?;
    let newline = source[marker_end..].chars().next()?;
    if !matches!(newline, '\n' | '\r') {
        return None;
    }
    let marker = &source[marker_start..marker_end];
    let mut line_start = marker_end + newline.len_utf8();
    while line_start < source.len() {
        let line_end = source[line_start..]
            .char_indices()
            .find_map(|(relative, character)| {
                matches!(character, '\n' | '\r').then_some(line_start + relative)
            })
            .unwrap_or(source.len());
        let content_start = source[line_start..line_end]
            .char_indices()
            .find_map(|(relative, character)| {
                (!matches!(character, ' ' | '\t')).then_some(line_start + relative)
            })
            .unwrap_or(line_end);
        if &source[content_start..line_end] == marker {
            return Some(line_end);
        }
        if line_end == source.len() {
            return None;
        }
        line_start = line_end + source[line_end..].chars().next()?.len_utf8();
    }
    None
}

fn consume_while(source: &str, offset: usize, predicate: impl Fn(char) -> bool) -> Option<usize> {
    let mut end = offset;
    for character in source[offset..].chars() {
        if !predicate(character) {
            break;
        }
        end += character.len_utf8();
    }
    (end > offset).then_some(end)
}

const SELECTIVE_GLR_BRANCH_BUDGET: usize = 256;

#[derive(Clone, Debug)]
struct ParserConfiguration {
    states: Vec<u32>,
    values: Vec<Value>,
    cursor: usize,
    score: i32,
}

#[derive(Clone, Debug)]
struct ParseCandidate {
    value: Value,
    cursor: usize,
    score: i32,
    ambiguities: usize,
    winner_reason: &'static str,
}

#[derive(Debug, Default)]
struct GlrContext {
    branches_explored: usize,
    speculative_branches_explored: usize,
    max_speculative_depth: usize,
    merged_branches: usize,
    successful_completions: usize,
    distinct_completions: Vec<Value>,
    best_failure: Option<Diagnostic>,
}

fn parse_tokens(
    spec: &LanguageSpec,
    tokens: &[Token<'_>],
) -> Result<(Value, SelectiveGlrReceipt), ParserFailure> {
    let significant = tokens
        .iter()
        .enumerate()
        .filter_map(|(index, token)| (!token.extra).then_some(index))
        .collect::<Vec<_>>();
    let mut context = GlrContext::default();
    let candidate = match run_configuration(
        spec,
        tokens,
        &significant,
        ParserConfiguration {
            states: vec![0],
            values: Vec::new(),
            cursor: 0,
            score: 0,
        },
        0,
        &mut context,
    ) {
        Ok(candidate) => candidate,
        Err(diagnostic) => {
            let selective_glr = (context.branches_explored > 0)
                .then(|| Box::new(selective_glr_receipt(&context, "no-completion", 0)));
            return Err(ParserFailure {
                diagnostic,
                selective_glr,
            });
        }
    };
    if candidate.ambiguities > 0 {
        return Err(ParserFailure {
            diagnostic: Diagnostic {
                reason_kind: "selective-glr-ambiguity",
                byte_offset: tokens.last().map_or(0, |token| token.end),
                message: format!(
                    "{} equal-score selective-GLR alternatives remain distinct",
                    candidate.ambiguities + 1
                ),
            },
            selective_glr: Some(Box::new(selective_glr_receipt(
                &context,
                "ambiguous",
                candidate.score,
            ))),
        });
    }
    let receipt = selective_glr_receipt(&context, candidate.winner_reason, candidate.score);
    Ok((candidate.value, receipt))
}

fn selective_glr_receipt(
    context: &GlrContext,
    winner_reason: &'static str,
    dynamic_score: i32,
) -> SelectiveGlrReceipt {
    SelectiveGlrReceipt {
        branch_budget: SELECTIVE_GLR_BRANCH_BUDGET,
        branches_explored: context.branches_explored,
        speculative_branches_explored: context.speculative_branches_explored,
        max_speculative_depth: context.max_speculative_depth,
        merged_branches: context.merged_branches,
        successful_completions: context.successful_completions,
        distinct_completions: context.distinct_completions.len(),
        winner_reason,
        dynamic_score,
    }
}

fn run_configuration(
    spec: &LanguageSpec,
    tokens: &[Token<'_>],
    significant: &[usize],
    mut configuration: ParserConfiguration,
    speculative_depth: usize,
    context: &mut GlrContext,
) -> Result<ParseCandidate, Diagnostic> {
    loop {
        let state = *configuration
            .states
            .last()
            .expect("LR state stack is never empty");
        let token = significant
            .get(configuration.cursor)
            .map(|index| &tokens[*index]);
        let Some(action) = find_action(spec, state, token) else {
            let diagnostic = Diagnostic {
                reason_kind: "parse-rejected",
                byte_offset: token
                    .map_or_else(|| tokens.last().map_or(0, |last| last.end), |t| t.start),
                message: format!("no LR action in state {state}"),
            };
            record_failure(context, &diagnostic);
            return Err(diagnostic);
        };
        match action {
            ParserAction::Shift(next) => {
                let Some(&token_index) = significant.get(configuration.cursor) else {
                    return Err(Diagnostic {
                        reason_kind: "invalid-aot-artifact",
                        byte_offset: tokens.last().map_or(0, |token| token.end),
                        message: "generated LR table shifts EOF".into(),
                    });
                };
                configuration.states.push(next);
                configuration.values.push(Value::Token(token_index));
                configuration.cursor += 1;
            }
            ParserAction::Reduce(production_id) => {
                apply_reduce(spec, tokens, token, &mut configuration, production_id)?;
            }
            ParserAction::Accept => {
                if configuration.cursor != significant.len() || configuration.values.len() != 1 {
                    return Err(Diagnostic {
                        reason_kind: "invalid-aot-artifact",
                        byte_offset: token.map_or(0, |token| token.start),
                        message: "generated accept action did not cover one complete root".into(),
                    });
                }
                let value = configuration
                    .values
                    .pop()
                    .expect("one accepted semantic value");
                record_completion(context, &value);
                return Ok(ParseCandidate {
                    value,
                    cursor: configuration.cursor,
                    score: configuration.score,
                    ambiguities: 0,
                    winner_reason: "unique-completion",
                });
            }
            ParserAction::RejectNonAssoc => {
                return Err(Diagnostic {
                    reason_kind: "parse-rejected",
                    byte_offset: token.map_or(0, |token| token.start),
                    message: "non-associative operator chain rejected".into(),
                });
            }
            ParserAction::Fork(branches) => {
                return explore_fork(
                    spec,
                    tokens,
                    significant,
                    configuration,
                    branches,
                    speculative_depth,
                    context,
                );
            }
        }
    }
}

fn apply_reduce(
    spec: &LanguageSpec,
    tokens: &[Token<'_>],
    token: Option<&Token<'_>>,
    configuration: &mut ParserConfiguration,
    production_id: u32,
) -> Result<(), Diagnostic> {
    let production = spec
        .productions
        .get(production_id as usize)
        .ok_or_else(|| Diagnostic {
            reason_kind: "invalid-aot-artifact",
            byte_offset: token.map_or(0, |token| token.start),
            message: format!("unknown production {production_id}"),
        })?;
    let count = production.rhs.len();
    if configuration.states.len() <= count || configuration.values.len() < count {
        return Err(Diagnostic {
            reason_kind: "invalid-aot-artifact",
            byte_offset: token.map_or(0, |token| token.start),
            message: format!("production {production_id} underflows the LR stack"),
        });
    }
    configuration
        .states
        .truncate(configuration.states.len() - count);
    let reduced_from = configuration
        .values
        .split_off(configuration.values.len() - count);
    let fallback = token.map_or_else(
        || tokens.last().map_or(0, |last| last.end),
        |lookahead| lookahead.start,
    );
    let reduced = reduce(production, reduced_from, tokens, fallback);
    let owner = *configuration.states.last().expect("LR owner state exists");
    let next = spec.gotos[owner as usize]
        .iter()
        .find(|entry| entry.nonterminal == production.lhs)
        .map(|entry| entry.state)
        .ok_or_else(|| Diagnostic {
            reason_kind: "invalid-aot-artifact",
            byte_offset: fallback,
            message: format!("missing goto for {} from state {owner}", production.lhs),
        })?;
    configuration.states.push(next);
    configuration.values.push(reduced);
    configuration.score += production.dynamic_precedence;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn explore_fork(
    spec: &LanguageSpec,
    tokens: &[Token<'_>],
    significant: &[usize],
    configuration: ParserConfiguration,
    branches: &[ParserAction],
    speculative_depth: usize,
    context: &mut GlrContext,
) -> Result<ParseCandidate, Diagnostic> {
    let mut best = None;
    for (index, branch) in branches.iter().enumerate() {
        context.branches_explored += 1;
        let branch_depth = speculative_depth + usize::from(index > 0);
        if index > 0 {
            context.speculative_branches_explored += 1;
            context.max_speculative_depth = context.max_speculative_depth.max(branch_depth);
        }
        if branch_depth > SELECTIVE_GLR_BRANCH_BUDGET {
            return Err(Diagnostic {
                reason_kind: "selective-glr-budget-exhausted",
                byte_offset: current_offset(tokens, significant, configuration.cursor),
                message: format!(
                    "selective-GLR speculative depth exceeds {}",
                    SELECTIVE_GLR_BRANCH_BUDGET
                ),
            });
        }
        match execute_branch_action(
            spec,
            tokens,
            significant,
            configuration.clone(),
            *branch,
            branch_depth,
            context,
        ) {
            Ok(candidate) => best = Some(better_candidate(best, candidate, context)),
            Err(diagnostic)
                if matches!(
                    diagnostic.reason_kind,
                    "invalid-aot-artifact" | "selective-glr-budget-exhausted"
                ) =>
            {
                return Err(diagnostic);
            }
            Err(diagnostic) => record_failure(context, &diagnostic),
        }
    }
    best.ok_or_else(|| {
        context.best_failure.clone().unwrap_or_else(|| Diagnostic {
            reason_kind: "parse-rejected",
            byte_offset: current_offset(tokens, significant, configuration.cursor),
            message: "no selective-GLR branch completed".into(),
        })
    })
}

#[allow(clippy::too_many_arguments)]
fn execute_branch_action(
    spec: &LanguageSpec,
    tokens: &[Token<'_>],
    significant: &[usize],
    mut configuration: ParserConfiguration,
    action: ParserAction,
    speculative_depth: usize,
    context: &mut GlrContext,
) -> Result<ParseCandidate, Diagnostic> {
    let token = significant
        .get(configuration.cursor)
        .map(|index| &tokens[*index]);
    match action {
        ParserAction::Shift(next) => {
            let Some(&token_index) = significant.get(configuration.cursor) else {
                return Err(Diagnostic {
                    reason_kind: "invalid-aot-artifact",
                    byte_offset: tokens.last().map_or(0, |token| token.end),
                    message: "generated LR table shifts EOF".into(),
                });
            };
            configuration.states.push(next);
            configuration.values.push(Value::Token(token_index));
            configuration.cursor += 1;
            run_configuration(
                spec,
                tokens,
                significant,
                configuration,
                speculative_depth,
                context,
            )
        }
        ParserAction::Reduce(production) => {
            apply_reduce(spec, tokens, token, &mut configuration, production)?;
            run_configuration(
                spec,
                tokens,
                significant,
                configuration,
                speculative_depth,
                context,
            )
        }
        ParserAction::Accept => {
            if configuration.cursor != significant.len() || configuration.values.len() != 1 {
                return Err(Diagnostic {
                    reason_kind: "invalid-aot-artifact",
                    byte_offset: current_offset(tokens, significant, configuration.cursor),
                    message: "generated accept action did not cover one complete root".into(),
                });
            }
            let value = configuration
                .values
                .pop()
                .expect("one accepted semantic value");
            record_completion(context, &value);
            Ok(ParseCandidate {
                value,
                cursor: configuration.cursor,
                score: configuration.score,
                ambiguities: 0,
                winner_reason: "unique-completion",
            })
        }
        ParserAction::RejectNonAssoc => Err(Diagnostic {
            reason_kind: "parse-rejected",
            byte_offset: current_offset(tokens, significant, configuration.cursor),
            message: "non-associative operator chain rejected".into(),
        }),
        ParserAction::Fork(branches) => explore_fork(
            spec,
            tokens,
            significant,
            configuration,
            branches,
            speculative_depth,
            context,
        ),
    }
}

fn better_candidate(
    current: Option<ParseCandidate>,
    candidate: ParseCandidate,
    context: &mut GlrContext,
) -> ParseCandidate {
    let Some(mut current) = current else {
        return candidate;
    };
    if candidate.score > current.score {
        return ParseCandidate {
            winner_reason: "dynamic-precedence",
            ..candidate
        };
    }
    if candidate.score < current.score {
        current.winner_reason = "dynamic-precedence";
        return current;
    }
    if candidate.cursor > current.cursor {
        return ParseCandidate {
            winner_reason: "maximal-consumption",
            ..candidate
        };
    }
    if candidate.cursor < current.cursor {
        current.winner_reason = "maximal-consumption";
        return current;
    }
    if candidate.value == current.value {
        context.merged_branches += 1;
        current.ambiguities += candidate.ambiguities;
        current.winner_reason = if current.ambiguities == 0 {
            "equivalent-merge"
        } else {
            "ambiguous"
        };
        current
    } else {
        current.ambiguities += candidate.ambiguities + 1;
        current.winner_reason = "ambiguous";
        current
    }
}

fn record_completion(context: &mut GlrContext, value: &Value) {
    context.successful_completions += 1;
    if !context
        .distinct_completions
        .iter()
        .any(|completion| completion == value)
    {
        context.distinct_completions.push(value.clone());
    }
}

fn record_failure(context: &mut GlrContext, diagnostic: &Diagnostic) {
    if context
        .best_failure
        .as_ref()
        .is_none_or(|current| diagnostic.byte_offset > current.byte_offset)
    {
        context.best_failure = Some(diagnostic.clone());
    }
}

fn current_offset(tokens: &[Token<'_>], significant: &[usize], cursor: usize) -> usize {
    significant.get(cursor).map_or_else(
        || tokens.last().map_or(0, |token| token.end),
        |index| tokens[*index].start,
    )
}

fn find_action(spec: &LanguageSpec, state: u32, token: Option<&Token<'_>>) -> Option<ParserAction> {
    let row = spec.actions.get(state as usize)?;
    if let Some(token) = token {
        row.iter()
            .find(|entry| match entry.terminal {
                Terminal::Literal(value) => {
                    if spec.case_insensitive {
                        value.eq_ignore_ascii_case(token.text)
                    } else {
                        value == token.text
                    }
                }
                _ => false,
            })
            .or_else(|| {
                row.iter().find(|entry| {
                    matches!(entry.terminal, Terminal::Token(name) if name == token.terminal)
                })
            })
            .map(|entry| entry.action)
    } else {
        row.iter()
            .find(|entry| entry.terminal == Terminal::Eof)
            .map(|entry| entry.action)
    }
}

fn reduce(
    production: &Production,
    values: Vec<Value>,
    tokens: &[Token<'_>],
    fallback: usize,
) -> Value {
    let mut groups = Vec::with_capacity(values.len());
    for (operand, mut value) in production.rhs.iter().zip(values) {
        for action in operand.actions {
            match *action {
                OperandAction::Field(field) => {
                    let mut children = value.into_children();
                    for child in &mut children {
                        child.field = Some(field);
                    }
                    value = Value::Fragment(children);
                }
                OperandAction::Alias(kind) => {
                    let start = value.start(tokens, fallback);
                    let end = value.end(tokens, fallback);
                    value = Value::Node {
                        kind,
                        start,
                        end,
                        children: value.into_children(),
                    };
                }
            }
        }
        groups.push(value);
    }
    match production.reduction {
        Reduction::Pass if groups.len() == 1 => groups.pop().expect("one pass operand"),
        Reduction::Pass | Reduction::Concat => {
            Value::Fragment(groups.into_iter().flat_map(Value::into_children).collect())
        }
    }
}

fn build_green(
    spec: &LanguageSpec,
    source: &str,
    tokens: &[Token<'_>],
    root: &Value,
) -> Result<GreenNode, String> {
    let Value::Node { kind, children, .. } = root else {
        return Err("accepted semantic value is not a syntax node".into());
    };
    if *kind != spec.root_kind {
        return Err("accepted syntax node does not have the declared root kind".into());
    }
    let mut builder = GreenNodeBuilder::new();
    let mut next_token = 0;
    builder.start_node(rowan::SyntaxKind(*kind));
    for child in children {
        emit_node(&mut builder, tokens, &child.value, &mut next_token)?;
    }
    while next_token < tokens.len() {
        emit_token(&mut builder, &tokens[next_token]);
        next_token += 1;
    }
    builder.finish_node();
    let green = builder.finish();
    if green.to_string() != source {
        return Err("Rowan tree does not reproduce the complete source".into());
    }
    Ok(green)
}

fn emit_node(
    builder: &mut GreenNodeBuilder<'_>,
    tokens: &[Token<'_>],
    value: &Value,
    next_token: &mut usize,
) -> Result<(), String> {
    match value {
        Value::Token(index) => {
            while *next_token < *index {
                emit_token(builder, &tokens[*next_token]);
                *next_token += 1;
            }
            if *next_token != *index {
                return Err("recognition token order is not monotonic".into());
            }
            emit_token(builder, &tokens[*index]);
            *next_token += 1;
        }
        Value::Node { kind, children, .. } => {
            builder.start_node(rowan::SyntaxKind(*kind));
            for child in children {
                emit_node(builder, tokens, &child.value, next_token)?;
            }
            builder.finish_node();
        }
        Value::Fragment(children) => {
            for child in children {
                emit_node(builder, tokens, &child.value, next_token)?;
            }
        }
    }
    Ok(())
}

fn emit_token(builder: &mut GreenNodeBuilder<'_>, token: &Token<'_>) {
    builder.token(rowan::SyntaxKind(token.syntax_kind), token.text);
}

pub mod generated;

#[cfg(test)]
mod lexical_tests {
    use super::{LexicalExpr, lexical_end};

    const NUMBER: LexicalExpr = LexicalExpr::NumberLiteral {
        prefixes: &["0x", "0o", "0b"],
        separator: "_",
        suffixes: &["M", "F", "D"],
        leading_period: true,
        trailing_period: true,
    };

    #[test]
    fn profiled_numbers_match_the_scheme_boundaries() {
        assert_eq!(lexical_end(&NUMBER, "0xCA_FE", 0), Some(7));
        assert_eq!(lexical_end(&NUMBER, "0o7_55", 0), Some(6));
        assert_eq!(lexical_end(&NUMBER, "0b10_01", 0), Some(7));
        assert_eq!(lexical_end(&NUMBER, "1_000.5E+2F", 0), Some(11));
        assert_eq!(lexical_end(&NUMBER, ".5M", 0), Some(3));
        assert_eq!(lexical_end(&NUMBER, "0x", 0), Some(1));
    }

    #[test]
    fn quoted_strings_preserve_doubled_and_backslash_escapes() {
        let expression = LexicalExpr::QuotedString(&["\"", "'", "`"]);
        assert_eq!(lexical_end(&expression, "`a``b`", 0), Some(6));
        assert_eq!(lexical_end(&expression, "'Ada''s graph'", 0), Some(14));
        assert_eq!(lexical_end(&expression, r#""a\"b""#, 0), Some(6));
        assert_eq!(lexical_end(&expression, "`unterminated", 0), None);
    }

    #[test]
    fn comments_and_choices_take_the_longest_complete_match() {
        let expression = LexicalExpr::Choice(&[
            LexicalExpr::LineComment(&["//", "#"]),
            LexicalExpr::BlockComment {
                opening: "/*",
                closing: "*/",
            },
        ]);
        assert_eq!(lexical_end(&expression, "// note\nnext", 0), Some(7));
        assert_eq!(lexical_end(&expression, "/* note */next", 0), Some(10));
        assert_eq!(lexical_end(&expression, "/* open", 0), None);
    }

    #[test]
    fn nested_comments_and_heredocs_close_losslessly() {
        let nested = LexicalExpr::NestedBlockComment {
            opening: "/*",
            closing: "*/",
        };
        assert_eq!(lexical_end(&nested, "/* /* */ */", 0), Some(11));
        assert_eq!(
            lexical_end(&LexicalExpr::Heredoc, "<<EOF\nvalue\nEOF", 0),
            Some(15)
        );
    }
}

